import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.BZKbe9n2.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"administration/configuration.md","filePath":"administration/configuration.md"}'),r={name:"administration/configuration.md"};function c(s,t,n,i,h,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>The server is configured with environment variables starting with <code>ANTHOLOGY_</code>. In the Quadlet files they are <code>Environment=</code> lines of <code>anthology-server.container</code>; in Compose they are under <code>environment:</code> of <code>anthology-server</code>.</p><h2 id="important-settings" tabindex="-1">Important settings <a class="header-anchor" href="#important-settings" aria-label="Permalink to &quot;Important settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>ANTHOLOGY_DATABASE_URL</code></td><td>set by the pod</td><td>PostgreSQL connection; the password comes from <code>ANTHOLOGY_DATABASE_PASSWORD_FILE</code></td></tr><tr><td><code>ANTHOLOGY_TIME_ZONE</code></td><td><code>UTC</code></td><td>time zone of schedules, e.g. <code>Europe/Zurich</code></td></tr><tr><td><code>ANTHOLOGY_IMPORT_ROOTS</code></td><td><code>/data/imports</code></td><td>folders admins may import from, comma-separated</td></tr><tr><td><code>ANTHOLOGY_MUSICBRAINZ_CONTACT</code></td><td>–</td><td>your e-mail or URL, sent to MusicBrainz as the required contact</td></tr><tr><td><code>ANTHOLOGY_ACOUSTID_API_KEY</code></td><td>–</td><td>enables fingerprint lookups at AcoustID</td></tr><tr><td><code>ANTHOLOGY_MUSICBRAINZ_URL</code></td><td>–</td><td>a local MusicBrainz mirror (no rate limit)</td></tr><tr><td><code>ANTHOLOGY_SOURCE_SERVICES</code></td><td>–</td><td>URLs of source services, comma-separated</td></tr><tr><td><code>ANTHOLOGY_RAUMFELD_HOSTS</code></td><td>–</td><td>Raumfeld host addresses when discovery cannot find them</td></tr><tr><td><code>ANTHOLOGY_OUTPUT_MEDIA_URL</code></td><td>–</td><td>the server&#39;s address as the speakers see it</td></tr><tr><td><code>ANTHOLOGY_TRANSCODE_CACHE_GB</code></td><td><code>20</code></td><td>size of the transcode cache</td></tr><tr><td><code>ANTHOLOGY_THUMBNAIL_CACHE_MB</code></td><td><code>512</code></td><td>size of the cover thumbnails</td></tr><tr><td><code>ANTHOLOGY_JOBS_THROTTLE</code></td><td><code>normal</code></td><td>background jobs at once: <code>gentle</code>, <code>normal</code>, <code>fast</code></td></tr></tbody></table><h2 id="data-volumes" tabindex="-1">Data volumes <a class="header-anchor" href="#data-volumes" aria-label="Permalink to &quot;Data volumes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Volume</th><th>Mounted at</th><th>Content</th><th>Back up</th></tr></thead><tbody><tr><td><code>anthology-library</code></td><td><code>/data/library</code></td><td>your music (originals) and the cover images</td><td>yes</td></tr><tr><td><code>anthology-db</code></td><td>PostgreSQL</td><td>the database</td><td>yes (<code>pg_dump</code>)</td></tr><tr><td><code>anthology-keys</code></td><td><code>/data/keys</code></td><td>signing keys; losing them signs out every device</td><td>yes</td></tr><tr><td><code>anthology-imports</code></td><td><code>/data/imports</code></td><td>incoming files</td><td>optional</td></tr><tr><td><code>anthology-cache</code></td><td><code>/data/cache</code></td><td>transcodes, tagged copies, thumbnails</td><td>no</td></tr></tbody></table><p>An existing collection can replace the library volume with a bind mount of a host folder (<code>Volume=/srv/music:/data/library:Z</code>); the server and the tagger need the same path.</p><h2 id="https-and-access-from-outside" tabindex="-1">HTTPS and access from outside <a class="header-anchor" href="#https-and-access-from-outside" aria-label="Permalink to &quot;HTTPS and access from outside&quot;">​</a></h2><p>The server speaks plain HTTP on port 8400. For access beyond your network, put a reverse proxy with TLS in front (for example Caddy, Traefik or nginx) and forward WebSocket upgrades for <code>/api/v1/ws</code>. The server trusts <code>X-Forwarded-*</code> headers from <code>127.0.0.1</code> only; set <code>FORWARDED_ALLOW_IPS</code> to the proxy&#39;s address if it runs elsewhere.</p>',9)])])}const _=e(r,[["render",c]]);export{u as __pageData,_ as default};
